@startuml
class Employee {
  +identifyingNumber : string
  +name : string
  +address : string
}

class AssemblyService {
  +kms : int
  +workHours : float
  +admissionDate : date
  +finishDate : date
}

class PartAccessory {
  +category : string
  +serialNumber : string
  +price : double
}

class Car {
  +licensePlate : string
  +make : string
  +model : string
  +color : string
}

class Owner {
  +name : string
  +identifyingNumber : string
  +address : string
  +phone : string
}

class CarModel {
  +name : string
}

Employee "1" -- "*" AssemblyService : responsible for
AssemblyService "*" -- "1" Car : executed in
AssemblyService "*" -- "*" PartAccessory : fits
PartAccessory "*" -- "*" CarModel : fits in
Car "1" -- "*" AssemblyService : undergoes
Car "*" -- "1" Owner : owned by
@enduml

